        else:
            score = abs(nx - (W - 1) / 2) + abs(ny - (H - 1) / 2)
        if opp_set and (nx, ny) in opp_set:
            score -= 1e6
        if opp_set:
            near_opp = 0
            for adx, ady in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                if (nx + adx, ny + ady) in opp_set:
